    }

    #[test]
    fn init_updates_gitignore() {
        let temp = TempDir::new().unwrap();
        fs::write(temp.path().join(".gitignore"), "node_modules\n").unwrap();

        let args = InitArgs {
            minimal: true,
            ..Default::default()
        };
