//! Bivvy CLI entry point.

use std::process::ExitCode;

use bivvy::cli::{Cli, CommandDispatcher, Commands};
use bivvy::shell::is_ci;
use bivvy::ui::{create_ui, OutputMode};
use bivvy::updates::{
    apply_staged_update, is_notification_suppressed, perform_background_update,
    should_spawn_background_update, show_update_notification, spawn_background_update,
};
use clap::Parser;
use tracing_subscriber::{fmt, prelude::*, EnvFilter};

/// Initialize the tracing subscriber for logging.
///
/// Log level is controlled by:
/// 1. `--debug` flag sets level to DEBUG
/// 2. `RUST_LOG` environment variable (if set)
/// 3. Default is INFO
fn init_tracing(debug: bool) {
    let filter = if debug {
        EnvFilter::new("bivvy=debug")
    } else {
        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("bivvy=info"))
    };

    tracing_subscriber::registry()
        .with(fmt::layer().with_target(false))
        .with(filter)
        .init();
}

fn main() -> ExitCode {
    // Safety net: claim the foreground process group for terminal I/O.
    //
    // When `cargo run` (or other launchers) spawn bivvy, the child may
    // not be the terminal's foreground process group. We ignore SIGTTOU
    // (so tcsetpgrp doesn't suspend us) and claim the foreground.
    //
    // The primary defense against SIGTTOU is using `-lc` (not `-lic`)
    // for child shell commands — see shell/command.rs. Without `-i`,
    // child shells don't set up job control and don't steal the
    // foreground group. These signal ignores and tcsetpgrp call are a
    // safety net for edge cases (e.g., `cargo run` wrappers).
    #[cfg(unix)]
    unsafe {
        libc::signal(libc::SIGTTOU, libc::SIG_IGN);
        libc::signal(libc::SIGTTIN, libc::SIG_IGN);

        let tty_fd = libc::open(c"/dev/tty".as_ptr(), libc::O_RDWR);
        if tty_fd >= 0 {
            libc::tcsetpgrp(tty_fd, libc::getpgrp());
            libc::close(tty_fd);
        }
    }

    // Background self-update process: when invoked with this env var,
    // perform the update check/download and exit immediately.
    if std::env::var("BIVVY_SELF_UPDATE_BG").is_ok() {
        let _ = perform_background_update();
        return ExitCode::SUCCESS;
    }

    let cli = Cli::parse();
    init_tracing(cli.debug);

    // Ensure ~/.bivvy/config.yml exists (first-run bootstrap).
    bivvy::config::ensure_global_config();

    tracing::debug!("Bivvy starting with args: {:?}", cli);

    // Determine output mode
    let output_mode = if cli.quiet {
        OutputMode::Quiet
    } else if cli.verbose {
        OutputMode::Verbose
    } else {
        OutputMode::Normal
    };

    // Handle --no-color
    if cli.no_color {
        std::env::set_var("NO_COLOR", "1");
    }

    // Determine project root
    let project_root = cli
        .project
        .as_ref()
        .cloned()
        .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());

    // Check if non-interactive (CI mode or explicit flag)
    let is_interactive = match &cli.command {
        Some(Commands::Run(args)) => !args.non_interactive && !args.ci && !is_ci(),
        _ => !is_ci(),
    };

    // Create UI
    let mut ui = create_ui(is_interactive, output_mode);

    // Apply any previously staged update (manual installs only).
    // This replaces the current binary before running the command,
    // so the user gets the new version immediately.
    match apply_staged_update() {
        Ok(Some(version)) => {
            tracing::info!("Auto-updated to v{}", version);
            ui.message(&format!("bivvy has been auto-updated to v{}", version));
        }
        Ok(None) => {} // No staged update
        Err(e) => {
            tracing::warn!("Failed to apply staged update: {}", e);
        }
    }

    // Dispatch command
    let dispatcher = CommandDispatcher::new(project_root);

    let exit_code = match dispatcher.dispatch(&cli, ui.as_mut()) {
        Ok(result) => {
            // Show update notification after successful runs
            if result.success && is_interactive && !is_notification_suppressed() {
                show_update_notification(ui.as_mut());
            }
            result.exit_code as u8
        }
        Err(e) => {
            ui.error(&format!("Error: {}", e));
            1
        }
    };

    // Spawn background update check after command completes.
    // This runs in a detached process so it doesn't delay the CLI exit.
    if should_spawn_background_update(is_interactive, is_ci()) {
        if let Err(e) = spawn_background_update() {
            tracing::debug!("Failed to spawn background update: {}", e);
        }
    }

    ExitCode::from(exit_code)
}

//! Template schema definitions.
//!
//! Templates are reusable step definitions that can be referenced
//! from configuration files.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;

/// A reusable step template.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Template {
    /// Template name (must be unique within source)
    pub name: String,

    /// Human-readable description
    pub description: String,

    /// Category for organization (e.g., "ruby", "node", "common")
    pub category: String,

    /// Semantic version
    #[serde(default = "default_version")]
    pub version: String,

    /// Minimum Bivvy version required
    pub min_bivvy_version: Option<String>,

    /// Platforms this template supports
    #[serde(default = "default_platforms")]
    pub platforms: Vec<Platform>,

    /// Detection rules to suggest this template
    #[serde(default)]
    pub detects: Vec<Detection>,

    /// Detector references for this template (additive alongside `detects`).
    ///
    /// Each entry is a dot-notation reference to a detector facet defined in
    /// `templates/detectors.yml` (e.g., `"rails.files.application_file"`).
    #[serde(default)]
    pub detectors: Vec<String>,

    /// Input contracts for this template
    #[serde(default)]
    pub inputs: HashMap<String, TemplateInput>,

    /// The step configuration this template provides
    pub step: TemplateStep,

    /// Environment impact after this step runs
    pub environment_impact: Option<EnvironmentImpact>,
}

fn default_version() -> String {
    "1.0.0".to_string()
}

fn default_platforms() -> Vec<Platform> {
    vec![Platform::MacOS, Platform::Linux, Platform::Windows]
}

/// Supported platforms.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Platform {
    MacOS,
    Linux,
    Windows,
}

impl Platform {
    /// Check if current platform matches.
    pub fn is_current(&self) -> bool {
        match self {
            Platform::MacOS => cfg!(target_os = "macos"),
            Platform::Linux => cfg!(target_os = "linux"),
            Platform::Windows => cfg!(target_os = "windows"),
        }
    }
}

/// Detection rule for auto-suggesting templates.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Detection {
    /// File that indicates this template applies
    pub file: Option<String>,

    /// Command that must succeed (exit 0)
    pub command: Option<String>,
}

/// Template input contract for parameterized templates.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TemplateInput {
    /// Human-readable description
    pub description: String,

    /// Input type
    #[serde(rename = "type")]
    pub input_type: InputType,

    /// Whether this input is required
    #[serde(default)]
    pub required: bool,

    /// Default value if not provided
    pub default: Option<serde_yaml::Value>,

    /// Valid values for enum type
    #[serde(default)]
    pub values: Vec<String>,

    /// Interactive prompt definition for this input.
    /// When present, the template automatically prompts for this input
    /// if it wasn't provided statically via `inputs:` in the config.
    #[serde(default)]
    pub prompt: Option<TemplateInputPrompt>,
}

/// Prompt definition embedded in a template input.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TemplateInputPrompt {
    /// Question to display
    pub question: String,

    /// Prompt type: select, input, confirm, multiselect
    #[serde(rename = "type")]
    pub prompt_type: crate::config::schema::PromptType,

    /// Options for select/multiselect
    #[serde(default)]
    pub options: Vec<crate::config::schema::PromptOption>,
}

impl TemplateInput {
    /// Validate a provided value against this input contract.
    pub fn validate(&self, name: &str, value: Option<&serde_yaml::Value>) -> Result<(), String> {
        match value {
            None => {
                if self.required && self.default.is_none() {
                    Err(format!("Required input '{}' is missing", name))
                } else {
                    Ok(())
                }
            }
            Some(v) => self.validate_type(name, v),
        }
    }

    fn validate_type(&self, name: &str, value: &serde_yaml::Value) -> Result<(), String> {
        match self.input_type {
            InputType::String => {
                if !value.is_string() {
                    return Err(format!("Input '{}' must be a string", name));
                }
            }
            InputType::Number => {
                if !value.is_number() {
                    return Err(format!("Input '{}' must be a number", name));
                }
            }
            InputType::Boolean => {
                if !value.is_bool() {
                    return Err(format!("Input '{}' must be a boolean", name));
                }
            }
            InputType::Enum => {
                let s = value
                    .as_str()
                    .ok_or_else(|| format!("Input '{}' must be a string (enum)", name))?;
                if !self.values.contains(&s.to_string()) {
                    return Err(format!(
                        "Input '{}' must be one of: {}",
                        name,
                        self.values.join(", ")
                    ));
                }
            }
        }
        Ok(())
    }

    /// Get effective value (provided or default).
    pub fn effective_value<'a>(
        &'a self,
        provided: Option<&'a serde_yaml::Value>,
    ) -> Option<&'a serde_yaml::Value> {
        provided.or(self.default.as_ref())
    }
}

/// Types of template inputs.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum InputType {
    String,
    Number,
    Boolean,
    Enum,
}

/// Step configuration provided by a template.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct TemplateStep {
    /// Step title (supports interpolation)
    pub title: Option<String>,

    /// Step description
    pub description: Option<String>,

    /// Command to execute
    pub command: Option<String>,

    /// Environment variables
    #[serde(default)]
    pub env: HashMap<String, String>,

    /// System-level prerequisites this template's step requires.
    #[serde(default)]
    pub requires: Vec<String>,
}

/// Environment impact after a step runs.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct EnvironmentImpact {
    /// Whether this step modifies PATH
    #[serde(default)]
    pub modifies_path: bool,

    /// Shell config files that may be modified
    #[serde(default)]
    pub shell_files: Vec<String>,

    /// Paths that will be added to PATH
    #[serde(default)]
    pub path_additions: Vec<String>,

    /// Note to display to user
    pub note: Option<String>,
}

/// Source of a template (for priority ordering).
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum TemplateSource {
    /// Project-local templates (.bivvy/templates/)
    Project,
    /// User-local templates (~/.bivvy/templates/)
    User,
    /// Remote templates (URL-based)
    Remote {
        /// Priority for remote sources (lower is higher priority)
        priority: u32,
    },
    /// Built-in templates (embedded in binary)
    Builtin,
}

